package it.unina.reservations.entity;

import jakarta.persistence.*;
import java.time.LocalDateTime;
import java.time.ZoneId;

/**
 * Generalizzazione degli attori registerti (Student, Librarian).
  * English implementation note.
 */
@Entity
@Inheritance(strategy = InheritanceType.JOINED)
public abstract class User{
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String name;
    private String surname;

    @Column(nullable = false, unique = true)
    private String institutionalEmail;

    private String password;

    // English implementation note.
    private int failedAttempts;
    private LocalDateTime lockedUntil;

    protected User() { /* Costruttore empty richiesto da JPA: l'istanza nasce dalle Factory (UC1). */ }

    // English implementation note.
    public Long getId() { return id; }

    public String getName() { return name; }
    public void setName(String name) { this.name = name; }

    public String getSurname() { return surname; }
    public void setSurname(String surname) { this.surname = surname; }

    public String getInstitutionalEmail() { return institutionalEmail; }
    public void setInstitutionalEmail(String institutionalEmail) { this.institutionalEmail = institutionalEmail; }

    public String getPassword() { return password; }
    public void setPassword(String password) { this.password = password; }

    public int getFailedAttempts() { return failedAttempts; }
    public void setFailedAttempts(int failedAttempts) { this.failedAttempts = failedAttempts; }

    public void setLockedUntilA(LocalDateTime lockedUntil) { this.lockedUntil = lockedUntil; }

    /** True se l'account risulta attualmente bloccato (blocco temporaneo non ancora scaduto). */
    public boolean isBloccato() {
        return lockedUntil != null && LocalDateTime.now(ZoneId.of("Europe/Rome")).isBefore(lockedUntil);
    }
}
