    /**
      * English implementation note.
      * English implementation note.
     */
    public boolean hasActiveOrConfirmedReservationForDateAndSlot(LocalDate date, String timeSlotLabel) {
        ReservationRegistry registry = ReservationRegistry.getInstance();
        for (Reservation p : registry.findActiveReservations(studentNumber, date)) {
            if (p.getTimeSlot() != null && timeSlotLabel.equals(p.getTimeSlot().getLabel())) {
                return true;
            }
        }
        return false;
    }
}
