package it.unina.reservations.database;

import jakarta.persistence.EntityManager;
import jakarta.persistence.TypedQuery;

import java.util.List;
import java.util.Map;

/**
  * English implementation note.
  * English implementation note.
  * English implementation note.
  * English implementation note.
  * English implementation note.
 */
public class PersistenceManager {

    /** English implementation note. */
    public boolean save(Object object) {
        EntityManager em = JpaUtil.getInstance().getEntityManager();

        try {
            em.getTransaction().begin();

            em.persist(object);

            em.getTransaction().commit();

            return true;

        } catch (RuntimeException e) {

            if (em.getTransaction().isActive()) {
                em.getTransaction().rollback();
            }

            e.printStackTrace();
            return false;

        } finally {
            em.close();
        }
    }

    /** English implementation note. */
    public boolean saveAll(Object... objects) {
        EntityManager em = JpaUtil.getInstance().getEntityManager();

        try {
            em.getTransaction().begin();

            for (Object object : objects) {
                em.persist(object);
            }

            em.getTransaction().commit();
            return true;

        } catch (RuntimeException e) {

            if (em.getTransaction().isActive()) {
                em.getTransaction().rollback();
            }

            e.printStackTrace();
            return false;

        } finally {
            em.close();
        }
    }

    /** English implementation note. */
    public <T> T findById(Class<T> entityClass, Long id) {

        EntityManager em = JpaUtil.getInstance().getEntityManager();

        try {
            return em.find(entityClass, id);

        } finally {
            em.close();
        }
    }

    /** English implementation note. */
    public <T> List<T> findByField(Class<T> entityClass,
            String fieldName,
            Object value) {

        return findByFields(
                entityClass,
                Map.of(fieldName, value));
    }

    /**
      * English implementation note.
      * English implementation note.
     */
    public <T> List<T> findByFields(Class<T> entityClass,
            Map<String, Object> fields) {

        EntityManager em = JpaUtil.getInstance().getEntityManager();

        try {
            StringBuilder jpql = new StringBuilder();

            jpql.append("SELECT e FROM ")
                    .append(entityClass.getSimpleName())
                    .append(" e");

            if (!fields.isEmpty()) {
                jpql.append(" WHERE ");

                int contatore = 0;

                for (String fieldName : fields.keySet()) {
                    if (contatore > 0) {
                        jpql.append(" AND ");
                    }

                    // English implementation note.
                    String parameterName = fieldName.replace(".", "_");

                    jpql.append("e.")
                            .append(fieldName)
                            .append(" = :")
                            .append(parameterName);

                    contatore++;
                }
            }

            TypedQuery<T> query = em.createQuery(
                    jpql.toString(),
                    entityClass);

            for (String fieldName : fields.keySet()) {
                String parameterName = fieldName.replace(".", "_");
                query.setParameter(parameterName, fields.get(fieldName));
            }

            return query.getResultList();

        } finally {
            em.close();
        }
    }

    /** English implementation note. */
    public <T> List<T> eseguiQueryCustom(String jpql, Class<T> entityClassRisultato, Map<String, Object> parametri) {

        EntityManager em = JpaUtil.getInstance().getEntityManager();

        try {
            TypedQuery<T> query = em.createQuery(jpql, entityClassRisultato);

            if (parametri != null && !parametri.isEmpty()) {
                for (Map.Entry<String, Object> parametro : parametri.entrySet()) {
                    query.setParameter(parametro.getKey(), parametro.getValue());
                }
            }

            return query.getResultList();

        } finally {
            em.close();
        }
    }

    /** English implementation note. */
    public <T> T findFirstByFields(Class<T> entityClass,
            Map<String, Object> fields) {

        List<T> results = findByFields(entityClass, fields);

        if (results.isEmpty()) {
            return null;
        }

        return results.get(0);
    }

    /** English implementation note. */
    public <T> T update(T object) {

        EntityManager em = JpaUtil.getInstance().getEntityManager();

        try {
            em.getTransaction().begin();

            T objectAggiornato = em.merge(object);

            em.getTransaction().commit();

            return objectAggiornato;

        } catch (RuntimeException e) {

            if (em.getTransaction().isActive()) {
                em.getTransaction().rollback();
            }

            throw e;

        } finally {
            em.close();
        }
    }

    /** English implementation note. */
    public <T> boolean deleteRoom(Class<T> entityClass, Long id) {

        EntityManager em = JpaUtil.getInstance().getEntityManager();

        try {
            em.getTransaction().begin();

            T object = em.find(entityClass, id);

            if (object != null) {
                em.remove(object);
                em.getTransaction().commit();
                return true;
            }

            em.getTransaction().commit();
            return false;

        } catch (RuntimeException e) {

            if (em.getTransaction().isActive()) {
                em.getTransaction().rollback();
            }

            e.printStackTrace();
            return false;

        } finally {
            em.close();
        }
    }

}
