    }

    /**
      * English implementation note.
      * English implementation note.
     */
    public <T> List<T> findByFields(Class<T> entityClass,
            Map<String, Object> fields) {

        EntityManager em = JpaUtil.getInstance().getEntityManager();

        try {
            StringBuilder jpql = new StringBuilder();

            jpql.append("SELECT e FROM ")
                    .append(entityClass.getSimpleName())
                    .append(" e");

            if (!fields.isEmpty()) {
                jpql.append(" WHERE ");

                int contatore = 0;

                for (String fieldName : fields.keySet()) {
                    if (contatore > 0) {
                        jpql.append(" AND ");
                    }

                    // English implementation note.
                    String parameterName = fieldName.replace(".", "_");

                    jpql.append("e.")
                            .append(fieldName)
                            .append(" = :")
                            .append(parameterName);

                    contatore++;
                }
            }

            TypedQuery<T> query = em.createQuery(
                    jpql.toString(),
                    entityClass);

            for (String fieldName : fields.keySet()) {
                String parameterName = fieldName.replace(".", "_");
                query.setParameter(parameterName, fields.get(fieldName));
            }

            return query.getResultList();

        } finally {
            em.close();
        }
    }

