    public <T> List<T> eseguiQueryCustom(String jpql, Class<T> entityClassRisultato, Map<String, Object> parametri) {

        EntityManager em = JpaUtil.getInstance().getEntityManager();

        try {
            TypedQuery<T> query = em.createQuery(jpql, entityClassRisultato);

            if (parametri != null && !parametri.isEmpty()) {
                for (Map.Entry<String, Object> parametro : parametri.entrySet()) {
                    query.setParameter(parametro.getKey(), parametro.getValue());
                }
            }

            return query.getResultList();

        } finally {
            em.close();
        }
    }

    /** English implementation note. */
    public <T> T findFirstByFields(Class<T> entityClass,
